WHERE s.year = 2021
  AND (t.name = 'Educational and Dacta'
       OR EXISTS {
         MATCH (t)-[:SUBTHEME_OF*1..10]->(parent:Theme)
         WHERE parent.name = 'Educational and Dacta'
       })
RETURN count(DISTINCT s) AS count;
```

```cypher
MATCH (s:Set {set_num: '9783960806707-1'})-[:HAS_INVENTORY]->(i:Inventory)
WITH s, i
ORDER BY i.version DESC
LIMIT 1
CALL {
    WITH i
    MATCH (i)-[e:CONTAINS_SET*0..10 (r, n | WHERE true)]->(nested:Inventory)
    WHERE (i)-[:HAS_INVENTORY]->(nested) OR EXISTS {
        MATCH (i)-[:CONTAINS_SET]->(mid:Set)-[:HAS_INVENTORY]->(nested)
    }
    WITH nested, list_product(properties(rels(e), 'qty')) AS path_qty
    MATCH (nested)-[hp:HAS_PART {is_spare: false}]->(p:Part)
    RETURN sum(hp.qty * path_qty) AS parts_from_sets
}
CALL {
    WITH i
    MATCH (i)-[e:CONTAINS_MINIFIG*0..10 (r, n | WHERE true)]->(mf:Minifig)-[:HAS_INVENTORY]->(mi:Inventory)
    WHERE (i)-[:CONTAINS_MINIFIG]->(mf) OR EXISTS {
        MATCH (i)-[:CONTAINS_SET]->(mid:Set)-[:HAS_INVENTORY]->(mfi:Inventory)-[:CONTAINS_MINIFIG]->(mf)
    }
    WITH mi, list_product(properties(rels(e), 'qty')) AS path_qty
    MATCH (mi)-[hp:HAS_PART {is_spare: false}]->(p:Part)
    RETURN sum(hp.qty * path_qty) AS parts_from_minifigs
}
CALL {
    WITH i
    MATCH (i)-[hp:HAS_PART {is_spare: false}]->(p:Part)
    RETURN sum(hp.qty) AS direct_parts
}
RETURN coalesce(direct_parts, 0) + coalesce(parts_from_sets, 0) + coalesce(parts_from_minifigs, 0) AS total_parts
```

```cypher
MATCH (s:Set {set_num: '66638-1'})-[:HAS_INVENTORY]->(inv:Inventory {version: 1})
MATCH (inv)-[:HAS_PART]->(p:Part)
WHERE NOT EXISTS {
    MATCH (inv)-[r:HAS_PART]->(p)
    WHERE r.is_spare = true
}
RETURN COUNT(DISTINCT p.part_num) AS count;
```

