MATCH (s:Set)-[:HAS_INVENTORY]->(inv:Inventory)
WHERE inv.version = (SELECT MAX(i2.version) FROM (s)-[:HAS_INVENTORY]->(i2:Inventory))
AND EXISTS {
  MATCH (inv)-[:CONTAINS_MINIFIG]->(:Minifig {fig_num: 'fig-013416'})
}
AND EXISTS {
  MATCH (inv)-[:HAS_PART]->(:Part {part_num: '78329'})
  WHERE NOT EXISTS { MATCH (inv)-[r:HAS_PART]->(:Part {part_num: '78329'}) WHERE r.is_spare = true }
}
RETURN COUNT(s)
